@AutoConfigureMockMvc
@DisplayName("禁飞区审查 HTTP API 端到端")
class AirspaceReviewControllerIT {

    @Autowired
    private MockMvc mockMvc;
    @Autowired
    private ObjectMapper objectMapper;
    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
